16 `include "common_cells/registers.svh"
17 
18 module fpnew_fma_multi #(
19   parameter fpnew_pkg::fmt_logic_t   FpFmtConfig = '1,
20   parameter int unsigned             NumPipeRegs = 0,
21   parameter fpnew_pkg::pipe_config_t PipeConfig  = fpnew_pkg::BEFORE,
22   parameter type                     TagType     = logic,
23   parameter type                     AuxType     = logic,
24   // Do not change
25   localparam int unsigned WIDTH       = fpnew_pkg::max_fp_width(FpFmtConfig),
26   localparam int unsigned NUM_FORMATS = fpnew_pkg::NUM_FP_FORMATS
27 ) (
28   input  logic                        clk_i,
29   input  logic                        rst_ni,
30   // Input signals
31   input  logic [2:0][WIDTH-1:0]       operands_i, // 3 operands
32   input  logic [NUM_FORMATS-1:0][2:0] is_boxed_i, // 3 operands
33   input  fpnew_pkg::roundmode_e       rnd_mode_i,
34   input  fpnew_pkg::operation_e       op_i,
35   input  logic                        op_mod_i,
36   input  fpnew_pkg::fp_format_e       src_fmt_i, // format of the multiplicands
37   input  fpnew_pkg::fp_format_e       dst_fmt_i, // format of the addend and result
38   input  TagType                      tag_i,
39   input  logic                        mask_i,
40   input  AuxType                      aux_i,
41   // Input Handshake
42   input  logic                        in_valid_i,
43   output logic                        in_ready_o,
44   input  logic                        flush_i,
45   // Output signals
46   output logic [WIDTH-1:0]            result_o,
47   output fpnew_pkg::status_t          status_o,
48   output logic                        extension_bit_o,
49   output TagType                      tag_o,
50   output logic                        mask_o,
51   output AuxType                      aux_o,
52   // Output handshake
53   output logic                        out_valid_o,
54   input  logic                        out_ready_i,
55   // Indication of valid data in flight
56   output logic                        busy_o
57 );
58 
59   // ----------
60   // Constants
61   // ----------
62   // The super-format that can hold all formats
63   localparam fpnew_pkg::fp_encoding_t SUPER_FORMAT = fpnew_pkg::super_format(FpFmtConfig);
64 
65   localparam int unsigned SUPER_EXP_BITS = SUPER_FORMAT.exp_bits;
66   localparam int unsigned SUPER_MAN_BITS = SUPER_FORMAT.man_bits;
67 
68   // Precision bits 'p' include the implicit bit
69   localparam int unsigned PRECISION_BITS = SUPER_MAN_BITS + 1;
70   // The lower 2p+3 bits of the internal FMA result will be needed for leading-zero detection
71   localparam int unsigned LOWER_SUM_WIDTH  = 2 * PRECISION_BITS + 3;
72   localparam int unsigned LZC_RESULT_WIDTH = $clog2(LOWER_SUM_WIDTH);
73   // Internal exponent width of FMA must accomodate all meaningful exponent values in order to avoid
74   // datapath leakage. This is either given by the exponent bits or the width of the LZC result.
75   // In most reasonable FP formats the internal exponent will be wider than the LZC result.
76   localparam int unsigned EXP_WIDTH = fpnew_pkg::maximum(SUPER_EXP_BITS + 2, LZC_RESULT_WIDTH);
77   // Shift amount width: maximum internal mantissa size is 3p+4 bits
78   localparam int unsigned SHIFT_AMOUNT_WIDTH = $clog2(3 * PRECISION_BITS + 5);
79   // Pipelines
80   localparam NUM_INP_REGS = PipeConfig == fpnew_pkg::BEFORE
81                             ? NumPipeRegs
82                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
83                                ? ((NumPipeRegs + 1) / 3) // Second to get distributed regs
84                                : 0); // no regs here otherwise
85   localparam NUM_MID_REGS = PipeConfig == fpnew_pkg::INSIDE
86                           ? NumPipeRegs
87                           : (PipeConfig == fpnew_pkg::DISTRIBUTED
88                              ? ((NumPipeRegs + 2) / 3) // First to get distributed regs
89                              : 0); // no regs here otherwise
90   localparam NUM_OUT_REGS = PipeConfig == fpnew_pkg::AFTER
91                             ? NumPipeRegs
92                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
93                                ? (NumPipeRegs / 3) // Last to get distributed regs
94                                : 0); // no regs here otherwise
95 
96   // ----------------
97   // Type definition
98   // ----------------
99   typedef struct packed {
100     logic                      sign;
101     logic [SUPER_EXP_BITS-1:0] exponent;
102     logic [SUPER_MAN_BITS-1:0] mantissa;
103   } fp_t;
104 
105   // ---------------
106   // Input pipeline
107   // ---------------
108   // Selected pipeline output signals as non-arrays
109   logic [2:0][WIDTH-1:0] operands_q;
110   fpnew_pkg::fp_format_e src_fmt_q;
111   fpnew_pkg::fp_format_e dst_fmt_q;
112 
113   // Input pipeline signals, index i holds signal after i register stages
114   logic                  [0:NUM_INP_REGS][2:0][WIDTH-1:0]       inp_pipe_operands_q;
115   logic                  [0:NUM_INP_REGS][NUM_FORMATS-1:0][2:0] inp_pipe_is_boxed_q;
116   fpnew_pkg::roundmode_e [0:NUM_INP_REGS]                       inp_pipe_rnd_mode_q;
117   fpnew_pkg::operation_e [0:NUM_INP_REGS]                       inp_pipe_op_q;
118   logic                  [0:NUM_INP_REGS]                       inp_pipe_op_mod_q;
119   fpnew_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_src_fmt_q;
120   fpnew_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_dst_fmt_q;
121   TagType                [0:NUM_INP_REGS]                       inp_pipe_tag_q;
122   logic                  [0:NUM_INP_REGS]                       inp_pipe_mask_q;
123   AuxType                [0:NUM_INP_REGS]                       inp_pipe_aux_q;
124   logic                  [0:NUM_INP_REGS]                       inp_pipe_valid_q;
125   // Ready signal is combinatorial for all stages
126   logic [0:NUM_INP_REGS] inp_pipe_ready;
127 
128   // Input stage: First element of pipeline is taken from inputs
129   assign inp_pipe_operands_q[0] = operands_i;
130   assign inp_pipe_is_boxed_q[0] = is_boxed_i;
131   assign inp_pipe_rnd_mode_q[0] = rnd_mode_i;
132   assign inp_pipe_op_q[0]       = op_i;
133   assign inp_pipe_op_mod_q[0]   = op_mod_i;
134   assign inp_pipe_src_fmt_q[0]  = src_fmt_i;
135   assign inp_pipe_dst_fmt_q[0]  = dst_fmt_i;
136   assign inp_pipe_tag_q[0]      = tag_i;
137   assign inp_pipe_mask_q[0]     = mask_i;
138   assign inp_pipe_aux_q[0]      = aux_i;
139   assign inp_pipe_valid_q[0]    = in_valid_i;
140   // Input stage: Propagate pipeline ready signal to updtream circuitry
141   assign in_ready_o = inp_pipe_ready[0];
142   // Generate the register stages
143   for (genvar i = 0; i < NUM_INP_REGS; i++) begin : gen_input_pipeline
144     // Internal register enable for this stage
145     logic reg_ena;
146     // Determine the ready signal of the current stage - advance the pipeline:
147     // 1. if the next stage is ready for our data
148     // 2. if the next stage only holds a bubble (not valid) -> we can pop it
149     assign inp_pipe_ready[i] = inp_pipe_ready[i+1] | ~inp_pipe_valid_q[i+1];
150     // Valid: enabled by ready signal, synchronous clear with the flush signal
151     `FFLARNC(inp_pipe_valid_q[i+1], inp_pipe_valid_q[i], inp_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
152     // Enable register if pipleine ready and a valid data item is present
153     assign reg_ena = inp_pipe_ready[i] & inp_pipe_valid_q[i];
154     // Generate the pipeline registers within the stages, use enable-registers
155     `FFL(inp_pipe_operands_q[i+1], inp_pipe_operands_q[i], reg_ena, '0)
156     `FFL(inp_pipe_is_boxed_q[i+1], inp_pipe_is_boxed_q[i], reg_ena, '0)
157     `FFL(inp_pipe_rnd_mode_q[i+1], inp_pipe_rnd_mode_q[i], reg_ena, fpnew_pkg::RNE)
158     `FFL(inp_pipe_op_q[i+1],       inp_pipe_op_q[i],       reg_ena, fpnew_pkg::FMADD)
159     `FFL(inp_pipe_op_mod_q[i+1],   inp_pipe_op_mod_q[i],   reg_ena, '0)
160     `FFL(inp_pipe_src_fmt_q[i+1],  inp_pipe_src_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
161     `FFL(inp_pipe_dst_fmt_q[i+1],  inp_pipe_dst_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
162     `FFL(inp_pipe_tag_q[i+1],      inp_pipe_tag_q[i],      reg_ena, TagType'('0))
163     `FFL(inp_pipe_mask_q[i+1],     inp_pipe_mask_q[i],     reg_ena, '0)
164     `FFL(inp_pipe_aux_q[i+1],      inp_pipe_aux_q[i],      reg_ena, AuxType'('0))
165   end
166   // Output stage: assign selected pipe outputs to signals for later use
167   assign operands_q = inp_pipe_operands_q[NUM_INP_REGS];
168   assign src_fmt_q  = inp_pipe_src_fmt_q[NUM_INP_REGS];
169   assign dst_fmt_q  = inp_pipe_dst_fmt_q[NUM_INP_REGS];
170 
171   // -----------------
172   // Input processing
173   // -----------------
174   logic        [NUM_FORMATS-1:0][2:0]                     fmt_sign;
175   logic signed [NUM_FORMATS-1:0][2:0][SUPER_EXP_BITS-1:0] fmt_exponent;
176   logic        [NUM_FORMATS-1:0][2:0][SUPER_MAN_BITS-1:0] fmt_mantissa;
177 
178   fpnew_pkg::fp_info_t [NUM_FORMATS-1:0][2:0] info_q;
179 
180   // FP Input initialization
181   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : fmt_init_inputs
182     // Set up some constants
183     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
184     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
185     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
186 
187     if (FpFmtConfig[fmt]) begin : active_format
188       logic [2:0][FP_WIDTH-1:0] trimmed_ops;
189 
190       // Classify input
191       fpnew_classifier #(
192         .FpFormat    ( fpnew_pkg::fp_format_e'(fmt) ),
193         .NumOperands ( 3                            )
194       ) i_fpnew_classifier (
195         .operands_i ( trimmed_ops                            ),
196         .is_boxed_i ( inp_pipe_is_boxed_q[NUM_INP_REGS][fmt] ),
197         .info_o     ( info_q[fmt]                            )
198       );
199       for (genvar op = 0; op < 3; op++) begin : gen_operands
200         assign trimmed_ops[op]       = operands_q[op][FP_WIDTH-1:0];
201         assign fmt_sign[fmt][op]     = operands_q[op][FP_WIDTH-1];
202         assign fmt_exponent[fmt][op] = signed'({1'b0, operands_q[op][MAN_BITS+:EXP_BITS]});
203         assign fmt_mantissa[fmt][op] = {info_q[fmt][op].is_normal, operands_q[op][MAN_BITS-1:0]} <<
204                                        (SUPER_MAN_BITS - MAN_BITS); // move to left of mantissa
205       end
206     end else begin : inactive_format
207       assign info_q[fmt]                 = '{default: fpnew_pkg::DONT_CARE}; // format disabled
208       assign fmt_sign[fmt]               = fpnew_pkg::DONT_CARE;             // format disabled
209       assign fmt_exponent[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
210       assign fmt_mantissa[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
211     end
212   end
213 
214   fp_t                 operand_a, operand_b, operand_c;
215   fpnew_pkg::fp_info_t info_a,    info_b,    info_c;
216 
217   // Operation selection and operand adjustment
218   // | \c op_q  | \c op_mod_q | Operation Adjustment
219   // |:--------:|:-----------:|---------------------
220   // | FMADD    | \c 0        | FMADD: none
221   // | FMADD    | \c 1        | FMSUB: Invert sign of operand C
222   // | FNMSUB   | \c 0        | FNMSUB: Invert sign of operand A
223   // | FNMSUB   | \c 1        | FNMADD: Invert sign of operands A and C
224   // | ADD      | \c 0        | ADD: Set operand A to +1.0
225   // | ADD      | \c 1        | SUB: Set operand A to +1.0, invert sign of operand C
226   // | MUL      | \c 0        | MUL: Set operand C to +0.0 or -0.0 depending on the rounding mode
227   // | *others* | \c -        | *invalid*
228   // \note \c op_mod_q always inverts the sign of the addend.
229   always_comb begin : op_select
230 
231     // Default assignments - packing-order-agnostic
232     operand_a = {fmt_sign[src_fmt_q][0], fmt_exponent[src_fmt_q][0], fmt_mantissa[src_fmt_q][0]};
233     operand_b = {fmt_sign[src_fmt_q][1], fmt_exponent[src_fmt_q][1], fmt_mantissa[src_fmt_q][1]};
234     operand_c = {fmt_sign[dst_fmt_q][2], fmt_exponent[dst_fmt_q][2], fmt_mantissa[dst_fmt_q][2]};
235     info_a    = info_q[src_fmt_q][0];
236     info_b    = info_q[src_fmt_q][1];
237     info_c    = info_q[dst_fmt_q][2];
238 
239     // op_mod_q inverts sign of operand C
240     operand_c.sign = operand_c.sign ^ inp_pipe_op_mod_q[NUM_INP_REGS];
241 
242     unique case (inp_pipe_op_q[NUM_INP_REGS])
243       fpnew_pkg::FMADD:  ; // do nothing
244       fpnew_pkg::FNMSUB: operand_a.sign = ~operand_a.sign; // invert sign of product
245       fpnew_pkg::ADD: begin // Set multiplicand to +1
246         operand_a = '{sign: 1'b0, exponent: fpnew_pkg::bias(src_fmt_q), mantissa: '0};
247         info_a    = '{is_normal: 1'b1, is_boxed: 1'b1, default: 1'b0}; //normal, boxed value.
248       end
249       fpnew_pkg::MUL: begin // Set addend to +0 or -0, depending whether the rounding mode is RDN
250         if (inp_pipe_rnd_mode_q[NUM_INP_REGS] == fpnew_pkg::RDN)
251           operand_c = '{sign: 1'b0, exponent: '0, mantissa: '0};
252         else
253           operand_c = '{sign: 1'b1, exponent: '0, mantissa: '0};
254         info_c    = '{is_zero: 1'b1, is_boxed: 1'b1, default: 1'b0}; //zero, boxed value.
255       end
256       default: begin // propagate don't cares
257         operand_a  = '{default: fpnew_pkg::DONT_CARE};
258         operand_b  = '{default: fpnew_pkg::DONT_CARE};
259         operand_c  = '{default: fpnew_pkg::DONT_CARE};
260         info_a     = '{default: fpnew_pkg::DONT_CARE};
261         info_b     = '{default: fpnew_pkg::DONT_CARE};
262         info_c     = '{default: fpnew_pkg::DONT_CARE};
263       end
264     endcase
265   end
266 
267   // ---------------------
268   // Input classification
269   // ---------------------
270   logic any_operand_inf;
271   logic any_operand_nan;
272   logic signalling_nan;
273   logic effective_subtraction;
274   logic tentative_sign;
275 
276   // Reduction for special case handling
277   assign any_operand_inf = (| {info_a.is_inf,        info_b.is_inf,        info_c.is_inf});
278   assign any_operand_nan = (| {info_a.is_nan,        info_b.is_nan,        info_c.is_nan});
279   assign signalling_nan  = (| {info_a.is_signalling, info_b.is_signalling, info_c.is_signalling});
280   // Effective subtraction in FMA occurs when product and addend signs differ
281   assign effective_subtraction = operand_a.sign ^ operand_b.sign ^ operand_c.sign;
282   // The tentative sign of the FMA shall be the sign of the product
283   assign tentative_sign = operand_a.sign ^ operand_b.sign;
284 
285   // ----------------------
286   // Special case handling
287   // ----------------------
288   logic [WIDTH-1:0]   special_result;
289   fpnew_pkg::status_t special_status;
290   logic               result_is_special;
291 
292   logic [NUM_FORMATS-1:0][WIDTH-1:0]    fmt_special_result;
293   fpnew_pkg::status_t [NUM_FORMATS-1:0] fmt_special_status;
294   logic [NUM_FORMATS-1:0]               fmt_result_is_special;
295 
296 
297   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_special_results
298     // Set up some constants
299     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
300     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
301     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
302 
303     localparam logic [EXP_BITS-1:0] QNAN_EXPONENT = '1;
304     localparam logic [MAN_BITS-1:0] QNAN_MANTISSA = 2**(MAN_BITS-1);
305     localparam logic [MAN_BITS-1:0] ZERO_MANTISSA = '0;
306 
307     if (FpFmtConfig[fmt]) begin : active_format
308       always_comb begin : special_results
309         logic [FP_WIDTH-1:0] special_res;
310 
311         // Default assignment
312         special_res                = {1'b0, QNAN_EXPONENT, QNAN_MANTISSA}; // qNaN
313         fmt_special_status[fmt]    = '0;
314         fmt_result_is_special[fmt] = 1'b0;
315 
316         // Handle potentially mixed nan & infinity input => important for the case where infinity and
317         // zero are multiplied and added to a qnan.
318         // RISC-V mandates raising the NV exception in these cases:
319         // (inf * 0) + c or (0 * inf) + c INVALID, no matter c (even quiet NaNs)
320         if ((info_a.is_inf && info_b.is_zero) || (info_a.is_zero && info_b.is_inf)) begin
321           fmt_result_is_special[fmt] = 1'b1; // bypass FMA, output is the canonical qNaN
322           fmt_special_status[fmt].NV = 1'b1; // invalid operation
323         // NaN Inputs cause canonical quiet NaN at the output and maybe invalid OP
324         end else if (any_operand_nan) begin
325           fmt_result_is_special[fmt] = 1'b1;           // bypass FMA, output is the canonical qNaN
326           fmt_special_status[fmt].NV = signalling_nan; // raise the invalid operation flag if signalling
327         // Special cases involving infinity
328         end else if (any_operand_inf) begin
329           fmt_result_is_special[fmt] = 1'b1; // bypass FMA
330           // Effective addition of opposite infinities (±inf - ±inf) is invalid!
331           if ((info_a.is_inf || info_b.is_inf) && info_c.is_inf && effective_subtraction)
332             fmt_special_status[fmt].NV = 1'b1; // invalid operation
333           // Handle cases where output will be inf because of inf product input
334           else if (info_a.is_inf || info_b.is_inf) begin
335             // Result is infinity with the sign of the product
336             special_res = {operand_a.sign ^ operand_b.sign, QNAN_EXPONENT, ZERO_MANTISSA};
337           // Handle cases where the addend is inf
338           end else if (info_c.is_inf) begin
339             // Result is inifinity with sign of the addend (= operand_c)
340             special_res = {operand_c.sign, QNAN_EXPONENT, ZERO_MANTISSA};
341           end
342         end
343         // Initialize special result with ones (NaN-box)
344         fmt_special_result[fmt]               = '1;
345         fmt_special_result[fmt][FP_WIDTH-1:0] = special_res;
346       end
347     end else begin : inactive_format
348       assign fmt_special_result[fmt] = '{default: fpnew_pkg::DONT_CARE};
349       assign fmt_special_status[fmt] = '0;
350       assign fmt_result_is_special[fmt] = 1'b0;
351     end
352   end
353 
354   // Detect special case from source format, I2F casts don't produce a special result
355   assign result_is_special = fmt_result_is_special[dst_fmt_q]; // they're all the same
356   // Signalling input NaNs raise invalid flag, otherwise no flags set
357   assign special_status = fmt_special_status[dst_fmt_q];
358   // Assemble result according to destination format
359   assign special_result = fmt_special_result[dst_fmt_q]; // destination format
360 
361   // ---------------------------
362   // Initial exponent data path
363   // ---------------------------
364   logic signed [EXP_WIDTH-1:0] exponent_a, exponent_b, exponent_c;
365   logic signed [EXP_WIDTH-1:0] exponent_addend, exponent_product, exponent_difference;
366   logic signed [EXP_WIDTH-1:0] tentative_exponent;
367 
368   // Zero-extend exponents into signed container - implicit width extension
369   assign exponent_a = signed'({1'b0, operand_a.exponent});
370   assign exponent_b = signed'({1'b0, operand_b.exponent});
371   assign exponent_c = signed'({1'b0, operand_c.exponent});
372 
373   // Calculate internal exponents from encoded values. Real exponents are (ex = Ex - bias + 1 - nx)
374   // with Ex the encoded exponent and nx the implicit bit. Internal exponents are biased to dst fmt.
375   assign exponent_addend = signed'(exponent_c + $signed({1'b0, ~info_c.is_normal})); // 0 as subnorm
376   // Biased product exponent is the sum of encoded exponents minus the bias.
377   assign exponent_product = (info_a.is_zero || info_b.is_zero) // in case the product is zero, set minimum exp.
378                             ? 2 - signed'(fpnew_pkg::bias(dst_fmt_q))
379                             : signed'(exponent_a + info_a.is_subnormal
380                                       + exponent_b + info_b.is_subnormal
381                                       - 2*signed'(fpnew_pkg::bias(src_fmt_q))
382                                       + signed'(fpnew_pkg::bias(dst_fmt_q))); // rebias for dst fmt
383   // Exponent difference is the addend exponent minus the product exponent
384   assign exponent_difference = exponent_addend - exponent_product;
385   // The tentative exponent will be the larger of the product or addend exponent
386   assign tentative_exponent = (exponent_difference > 0) ? exponent_addend : exponent_product;
387 
388   // Shift amount for addend based on exponents (unsigned as only right shifts)
389   logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt;
390 
391   always_comb begin : addend_shift_amount
392     // Product-anchored case, saturated shift (addend is only in the sticky bit)
393     if (exponent_difference <= signed'(-2 * PRECISION_BITS - 1))
394       addend_shamt = 3 * PRECISION_BITS + 4;
395     // Addend and product will have mutual bits to add
396     else if (exponent_difference <= signed'(PRECISION_BITS + 2))
397       addend_shamt = unsigned'(signed'(PRECISION_BITS) + 3 - exponent_difference);
398     // Addend-anchored case, saturated shift (product is only in the sticky bit)
399     else
400       addend_shamt = 0;
401   end
402 
403   // ------------------
404   // Product data path
405   // ------------------
406   logic [PRECISION_BITS-1:0]   mantissa_a, mantissa_b, mantissa_c;
407   logic [2*PRECISION_BITS-1:0] product;             // the p*p product is 2p bits wide
408   logic [3*PRECISION_BITS+3:0] product_shifted;     // addends are 3p+4 bit wide (including G/R)
409 
410   // Add implicit bits to mantissae
411   assign mantissa_a = {info_a.is_normal, operand_a.mantissa};
412   assign mantissa_b = {info_b.is_normal, operand_b.mantissa};
413   assign mantissa_c = {info_c.is_normal, operand_c.mantissa};
414 
415   // Mantissa multiplier (a*b)
416   assign product = mantissa_a * mantissa_b;
417 
418   // Product is placed into a 3p+4 bit wide vector, padded with 2 bits for round and sticky:
419   // | 000...000 | product | RS |
420   //  <-  p+2  -> <-  2p -> < 2>
421   assign product_shifted = product << 2; // constant shift
422 
423   // -----------------
424   // Addend data path
425   // -----------------
426   logic [3*PRECISION_BITS+3:0] addend_after_shift;  // upper 3p+4 bits are needed to go on
427   logic [PRECISION_BITS-1:0]   addend_sticky_bits;  // up to p bit of shifted addend are sticky
428   logic                        sticky_before_add;   // they are compressed into a single sticky bit
429   logic [3*PRECISION_BITS+3:0] addend_shifted;      // addends are 3p+4 bit wide (including G/R)
430   logic                        inject_carry_in;     // inject carry for subtractions if needed
431 
432   // In parallel, the addend is right-shifted according to the exponent difference. Up to p bits are
433   // shifted out and compressed into a sticky bit.
434   // BEFORE THE SHIFT:
435   // | mantissa_c | 000..000 |
436   //  <-    p   -> <- 3p+4 ->
437   // AFTER THE SHIFT:
438   // | 000..........000 | mantissa_c | 000...............0GR |  sticky bits  |
439   //  <- addend_shamt -> <-    p   -> <- 2p+4-addend_shamt -> <-  up to p  ->
440   assign {addend_after_shift, addend_sticky_bits} =
441       (mantissa_c << (3 * PRECISION_BITS + 4)) >> addend_shamt;
442 
443   assign sticky_before_add     = (| addend_sticky_bits);
444 
445   // In case of a subtraction, the addend is inverted
446   assign addend_shifted = (effective_subtraction) ? ~addend_after_shift : addend_after_shift;
447   assign inject_carry_in = effective_subtraction & ~sticky_before_add;
448 
449   // ------
450   // Adder
451   // ------
452   logic [3*PRECISION_BITS+4:0] sum_raw;   // added one bit for the carry
453   logic                        sum_carry; // observe carry bit from sum for sign fixing
454   logic [3*PRECISION_BITS+3:0] sum;       // discard carry as sum won't overflow
455   logic                        final_sign;
456 
457   //Mantissa adder (ab+c). In normal addition, it cannot overflow.
458   assign sum_raw = product_shifted + addend_shifted + inject_carry_in;
459   assign sum_carry = sum_raw[3*PRECISION_BITS+4];
460 
461   // Complement negative sum (can only happen in subtraction -> overflows for positive results)
462   assign sum        = (effective_subtraction && ~sum_carry) ? -sum_raw : sum_raw;
463 
464   // In case of a mispredicted subtraction result, do a sign flip
465   assign final_sign = (effective_subtraction && (sum_carry == tentative_sign))
466                       ? 1'b1
467                       : (effective_subtraction ? 1'b0 : tentative_sign);
468 
