561   assign exponent_difference_q   = mid_pipe_exp_diff_q[NUM_MID_REGS];
562   assign tentative_exponent_q    = mid_pipe_tent_exp_q[NUM_MID_REGS];
563   assign addend_shamt_q          = mid_pipe_add_shamt_q[NUM_MID_REGS];
564   assign sticky_before_add_q     = mid_pipe_sticky_q[NUM_MID_REGS];
