573   // --------------
574   // Normalization
575   // --------------
576   logic        [LOWER_SUM_WIDTH-1:0]  sum_lower;              // lower 2p+3 bits of sum are searched
577   logic        [LZC_RESULT_WIDTH-1:0] leading_zero_count;     // the number of leading zeroes
578   logic signed [LZC_RESULT_WIDTH:0]   leading_zero_count_sgn; // signed leading-zero count
579   logic                               lzc_zeroes;             // in case only zeroes found
580 
581   logic        [SHIFT_AMOUNT_WIDTH-1:0] norm_shamt; // Normalization shift amount
582   logic signed [EXP_WIDTH-1:0]          normalized_exponent;
583 
584   logic [3*PRECISION_BITS+4:0] sum_shifted;       // result after first normalization shift
585   logic [PRECISION_BITS:0]     final_mantissa;    // final mantissa before rounding with round bit
586   logic [2*PRECISION_BITS+2:0] sum_sticky_bits;   // remaining 2p+3 sticky bits after normalization
587   logic                        sticky_after_norm; // sticky bit after normalization
588 
589   logic signed [EXP_WIDTH-1:0] final_exponent;
590 
591   assign sum_lower = sum_q[LOWER_SUM_WIDTH-1:0];
592 
593   // Leading zero counter for cancellations
594   lzc #(
595     .WIDTH ( LOWER_SUM_WIDTH ),
596     .MODE  ( 1               ) // MODE = 1 counts leading zeroes
597   ) i_lzc (
598     .in_i    ( sum_lower          ),
599     .cnt_o   ( leading_zero_count ),
600     .empty_o ( lzc_zeroes         )
601   );
602 
603   assign leading_zero_count_sgn = signed'({1'b0, leading_zero_count});
604 
605   // Normalization shift amount based on exponents and LZC (unsigned as only left shifts)
606   always_comb begin : norm_shift_amount
607     // Product-anchored case or cancellations require LZC
608     if ((exponent_difference_q <= 0) || (effective_subtraction_q && (exponent_difference_q <= 2))) begin
609       // Normal result (biased exponent > 0 and not a zero)
610       if ((exponent_product_q - leading_zero_count_sgn + 1 >= 0) && !lzc_zeroes) begin
611         // Undo initial product shift, remove the counted zeroes
612         norm_shamt          = PRECISION_BITS + 2 + leading_zero_count;
613         normalized_exponent = exponent_product_q - leading_zero_count_sgn + 1; // account for shift
614       // Subnormal result
615       end else begin
616         // Cap the shift distance to align mantissa with minimum exponent
617         norm_shamt          = unsigned'(signed'(PRECISION_BITS + 2 + exponent_product_q));
618         normalized_exponent = 0; // subnormals encoded as 0
619       end
620     // Addend-anchored case
621     end else begin
622       norm_shamt          = addend_shamt_q; // Undo the initial shift
623       normalized_exponent = tentative_exponent_q;
624     end
625   end
626 
627   // Do the large normalization shift
628   assign sum_shifted       = sum_q << norm_shamt;
629 
630   // The addend-anchored case needs a 1-bit normalization since the leading-one can be to the left
631   // or right of the (non-carry) MSB of the sum.
632   always_comb begin : small_norm
633     // Default assignment, discarding carry bit
634     {final_mantissa, sum_sticky_bits} = sum_shifted;
635     final_exponent                    = normalized_exponent;
636 
637     // The normalized sum has overflown, align right and fix exponent
638     if (sum_shifted[3*PRECISION_BITS+4]) begin // check the carry bit
639       {final_mantissa, sum_sticky_bits} = sum_shifted >> 1;
640       final_exponent                    = normalized_exponent + 1;
641     // The normalized sum is normal, nothing to do
642     end else if (sum_shifted[3*PRECISION_BITS+3]) begin // check the sum MSB
643       // do nothing
644     // The normalized sum is still denormal, align left - unless the result is not already subnormal
645     end else if (normalized_exponent > 1) begin
646       {final_mantissa, sum_sticky_bits} = sum_shifted << 1;
647       final_exponent                    = normalized_exponent - 1;
648     // Otherwise we're denormal
649     end else begin
650       final_exponent = '0;
651     end
652   end
653 
654   // Update the sticky bit with the shifted-out bits
655   assign sticky_after_norm = (| {sum_sticky_bits}) | sticky_before_add_q;
656 
657   // ----------------------------
658   // Rounding and classification
659   // ----------------------------
660   logic                                     pre_round_sign;
661   logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] pre_round_abs; // absolute value of result before rounding
662   logic [1:0]                               round_sticky_bits;
663 
664   logic of_before_round, of_after_round; // overflow
665   logic uf_before_round, uf_after_round; // underflow
666 
667   logic [NUM_FORMATS-1:0][SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] fmt_pre_round_abs; // per format
668   logic [NUM_FORMATS-1:0][1:0]                               fmt_round_sticky_bits;
669 
670   logic [NUM_FORMATS-1:0]                                    fmt_of_after_round;
671   logic [NUM_FORMATS-1:0]                                    fmt_uf_after_round;
672 
673   logic                                     rounded_sign;
674   logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] rounded_abs; // absolute value of result after rounding
675   logic                                     result_zero;
676 
677   // Classification before round. RISC-V mandates checking underflow AFTER rounding!
678   assign of_before_round = final_exponent >= 2**(fpnew_pkg::exp_bits(dst_fmt_q2))-1; // infinity exponent is all ones
679   assign uf_before_round = final_exponent == 0;               // exponent for subnormals capped to 0
680 
681   // Pack exponent and mantissa into proper rounding form
682   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_res_assemble
683     // Set up some constants
684     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
685     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
686 
687     logic [EXP_BITS-1:0] pre_round_exponent;
688     logic [MAN_BITS-1:0] pre_round_mantissa;
689 
690     if (FpFmtConfig[fmt]) begin : active_format
691 
692       assign pre_round_exponent = (of_before_round) ? 2**EXP_BITS-2 : final_exponent[EXP_BITS-1:0];
693       assign pre_round_mantissa = (of_before_round) ? '1 : final_mantissa[SUPER_MAN_BITS-:MAN_BITS];
694       // Assemble result before rounding. In case of overflow, the largest normal value is set.
695       assign fmt_pre_round_abs[fmt] = {pre_round_exponent, pre_round_mantissa}; // 0-extend
696 
697       // Round bit is after mantissa (1 in case of overflow for rounding)
698       assign fmt_round_sticky_bits[fmt][1] = final_mantissa[SUPER_MAN_BITS-MAN_BITS] |
699                                              of_before_round;
700 
701       // remaining bits in mantissa to sticky (1 in case of overflow for rounding)
702       if (MAN_BITS < SUPER_MAN_BITS) begin : narrow_sticky
703         assign fmt_round_sticky_bits[fmt][0] = (| final_mantissa[SUPER_MAN_BITS-MAN_BITS-1:0]) |
704                                                sticky_after_norm | of_before_round;
705       end else begin : normal_sticky
706         assign fmt_round_sticky_bits[fmt][0] = sticky_after_norm | of_before_round;
707       end
708     end else begin : inactive_format
709       assign fmt_pre_round_abs[fmt] = '{default: fpnew_pkg::DONT_CARE};
710       assign fmt_round_sticky_bits[fmt] = '{default: fpnew_pkg::DONT_CARE};
711     end
712   end
713 
714   // Assemble result before rounding. In case of overflow, the largest normal value is set.
715   assign pre_round_sign     = final_sign_q;
716   assign pre_round_abs      = fmt_pre_round_abs[dst_fmt_q2];
717 
718   // In case of overflow, the round and sticky bits are set for proper rounding
719   assign round_sticky_bits  = fmt_round_sticky_bits[dst_fmt_q2];
720 
721   // Perform the rounding
722   fpnew_rounding #(
723     .AbsWidth ( SUPER_EXP_BITS + SUPER_MAN_BITS )
724   ) i_fpnew_rounding (
725     .abs_value_i             ( pre_round_abs           ),
726     .sign_i                  ( pre_round_sign          ),
727     .round_sticky_bits_i     ( round_sticky_bits       ),
728     .rnd_mode_i              ( rnd_mode_q              ),
729     .effective_subtraction_i ( effective_subtraction_q ),
730     .abs_rounded_o           ( rounded_abs             ),
731     .sign_o                  ( rounded_sign            ),
732     .exact_zero_o            ( result_zero             )
733   );
734 
735   logic [NUM_FORMATS-1:0][WIDTH-1:0] fmt_result;
736 
737   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_sign_inject
738     // Set up some constants
739     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
740     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
741     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
742 
743     if (FpFmtConfig[fmt]) begin : active_format
744       always_comb begin : post_process
745         // detect of / uf
746         fmt_uf_after_round[fmt] = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0; // denormal
747         fmt_of_after_round[fmt] = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '1; // inf exp.
748 
749         // Assemble regular result, nan box short ones.
750         fmt_result[fmt]               = '1;
751         fmt_result[fmt][FP_WIDTH-1:0] = {rounded_sign, rounded_abs[EXP_BITS+MAN_BITS-1:0]};
752       end
753     end else begin : inactive_format
754       assign fmt_uf_after_round[fmt] = fpnew_pkg::DONT_CARE;
755       assign fmt_of_after_round[fmt] = fpnew_pkg::DONT_CARE;
756       assign fmt_result[fmt]         = '{default: fpnew_pkg::DONT_CARE};
757     end
758   end
759 
760   // Classification after rounding select by destination format
761   assign uf_after_round = fmt_uf_after_round[dst_fmt_q2];
762   assign of_after_round = fmt_of_after_round[dst_fmt_q2];
763 
764 
765   // -----------------
766   // Result selection
767   // -----------------
768   logic [WIDTH-1:0]     regular_result;
769   fpnew_pkg::status_t   regular_status;
770 
771   // Assemble regular result
772   assign regular_result = fmt_result[dst_fmt_q2];
773   assign regular_status.NV = 1'b0; // only valid cases are handled in regular path
774   assign regular_status.DZ = 1'b0; // no divisions
775   assign regular_status.OF = of_before_round | of_after_round;   // rounding can introduce overflow
