777   assign regular_status.NX = (| round_sticky_bits) | of_before_round | of_after_round;
778 
779   // Final results for output pipeline
780   logic [WIDTH-1:0]   result_d;
781   fpnew_pkg::status_t status_d;
782 
783   // Select output depending on special case detection
784   assign result_d = result_is_special_q ? special_result_q : regular_result;
