787   // ----------------
788   // Output Pipeline
789   // ----------------
790   // Output pipeline signals, index i holds signal after i register stages
791   logic               [0:NUM_OUT_REGS][WIDTH-1:0] out_pipe_result_q;
792   fpnew_pkg::status_t [0:NUM_OUT_REGS]            out_pipe_status_q;
793   TagType             [0:NUM_OUT_REGS]            out_pipe_tag_q;
794   logic               [0:NUM_OUT_REGS]            out_pipe_mask_q;
795   AuxType             [0:NUM_OUT_REGS]            out_pipe_aux_q;
796   logic               [0:NUM_OUT_REGS]            out_pipe_valid_q;
797   // Ready signal is combinatorial for all stages
798   logic [0:NUM_OUT_REGS] out_pipe_ready;
799 
800   // Input stage: First element of pipeline is taken from inputs
801   assign out_pipe_result_q[0] = result_d;
802   assign out_pipe_status_q[0] = status_d;
803   assign out_pipe_tag_q[0]    = mid_pipe_tag_q[NUM_MID_REGS];
804   assign out_pipe_mask_q[0]   = mid_pipe_mask_q[NUM_MID_REGS];
805   assign out_pipe_aux_q[0]    = mid_pipe_aux_q[NUM_MID_REGS];
806   assign out_pipe_valid_q[0]  = mid_pipe_valid_q[NUM_MID_REGS];
807   // Input stage: Propagate pipeline ready signal to inside pipe
808   assign mid_pipe_ready[NUM_MID_REGS] = out_pipe_ready[0];
809   // Generate the register stages
810   for (genvar i = 0; i < NUM_OUT_REGS; i++) begin : gen_output_pipeline
811     // Internal register enable for this stage
812     logic reg_ena;
813     // Determine the ready signal of the current stage - advance the pipeline:
814     // 1. if the next stage is ready for our data
815     // 2. if the next stage only holds a bubble (not valid) -> we can pop it
816     assign out_pipe_ready[i] = out_pipe_ready[i+1] | ~out_pipe_valid_q[i+1];
817     // Valid: enabled by ready signal, synchronous clear with the flush signal
